-- ===================== GDOCS =====================
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_a37b403d5200d4f0a31d31', 'Stockholder close-out notes', 'leonard.hayes@harmonygames.co', '[]', 'private', E'Stockholder close-out notes\n\nThese replace my earlier outreach notes.\n\nWhat needs doing\n- the reach-out I promised to the investors, one by one, not one mail to everyone\n- where I left things today in #winddown: the angels are what''s open from my list, besides the Sunset onboarding\n- the investor email on the Task List: take my draft from #winddown and bring it up to date as a letter I can send. the update outline has the sections\n- the holder sheet comes first, the notes and everything else run off it. Share it and the letter with Robert\n- notes ready for me by Tuesday, as Gmail drafts. I said I''d archive google after the 15th but that waits, we keep it until the data is extracted, so my drafts are safe until I''ve gone through them. I read and send each note myself\n- everything goes in the close-out folder, not the Wind Down one, that one is the vendor and termination papers\n- Griffin''s partner gets a heads-up as a reply on the Feb 12 Board position thread, with what we still need from Griffin. That one can go out once the sheet is done\n- when the sheet is ready, reply under my list in #winddown and say who goes first\n\nHow each holder gets handled\n- Carta is the record. If a line''s last day has passed, it holds nothing.\n- One row per issue on the sheet and at most one note per person. The three of us get no row, only the totals.\n- Told means a written message about the closing, sent to them directly, from one of the three of us; for a fund, its partner.\n- Everyone still holding something gets what they are owed: the closing if they have not been told, their last day if they have one. Whoever''s last day comes first goes first.\n- Each note says what they hold.\n- Anything they asked about their holding that we never answered gets answered in their note, if they get one.\n- Notice route: the email we have, unless a document says otherwise.\n\nLabels for the sheet: Nothing, Already told, Closing, Last day, Closing and last day.\n', '[{"start": 0, "end": 28, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 28, "end": 1955, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '3c986c6ce3', 'f_a37b403d5200d4f0a31d31', '2026-02-13T01:05:41Z', '2026-02-13T01:05:41Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_762c60832854d3e7a7f7df', 'Holder outreach notes', 'leonard.hayes@harmonygames.co', '[]', 'private', E'Holder outreach notes\n\nRough plan, before I forget.\n\n- Griffin first, then everyone else\n- one email to everyone on the investor list, same note for all of them, BCC like the update\n- take the names and numbers from the Nov 2024 owner list\n- ask Robert and Arthur to read it before it goes\n', '[{"start": 0, "end": 22, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 22, "end": 290, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '84bdd1a5ac', 'f_762c60832854d3e7a7f7df', '2026-02-10T17:41:09Z', '2026-02-10T17:41:09Z');
