INSERT INTO linear.linear_projects (id, team_id, name, summary, description, lead_id, priority, state, start_date, target_date, labels_json, links_json, is_archived, created_at, updated_at)
VALUES ('ec2ea957-fc8e-4958-b809-0fb735b1e916', 'team_ENG', 'Holder records', NULL, E'The holders, as I said in #winddown: one issue per holder on Carta, live or lapsed, the three of us aside. my close-out notes have how each holder gets handled, and the sheet is what Sunset asked for. I''ll pass it to Sunset myself. Send KPMG''s confirmation as a reply to all once the sheet is done.\n\nStates once the sheet is done: Canceled where the line holds nothing; otherwise Todo where its own note is waiting for me, and Done where it isn''t. On every issue with no note of its own, Canceled included, say why.', 'usr_63fffeb4fab5233e', 0, 'started', '2026-02-12', NULL, '[]', '[]', false, '2026-02-12T23:24:12Z', '2026-02-13T18:21:46Z');
